// Parse the arXiv Atom feed, drop papers already sent, pre-score by keywords.
const TOPICS = ['robot', 'manipulat', 'slam', 'lidar', 'event camera', 'neuromorphic', 'reinforcement',
  'agent', 'language model', 'vision-language', 'trading', 'portfolio', 'spacecraft', 'uav', 'drone'];
const MAX_AGE_HOURS = 36;
const KEEP = 15;

const xml = $input.first().json.data || '';
const unescape = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
const tag = (block, name) => {
  const m = block.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`));
  return m ? unescape(m[1]).replace(/\s+/g, ' ').trim() : '';
};

const seen = $getWorkflowStaticData('global');
seen.ids = seen.ids || [];
const now = Date.now();
const papers = [];
for (const block of xml.split('<entry>').slice(1)) {
  const id = tag(block, 'id');
  const published = tag(block, 'published');
  const ageH = (now - Date.parse(published)) / 36e5;
  if (!id || seen.ids.includes(id) || !(ageH <= MAX_AGE_HOURS)) continue;
  const title = tag(block, 'title');
  const summary = tag(block, 'summary');
  const authors = [...block.matchAll(/<name>([\s\S]*?)<\/name>/g)].map((m) => m[1].trim());
  const text = `${title} ${summary}`.toLowerCase();
  const keywordScore = TOPICS.filter((t) => text.includes(t)).length;
  papers.push({ id, title, summary: summary.slice(0, 900), authors: authors.slice(0, 4), published, keywordScore });
}
papers.sort((a, b) => b.keywordScore - a.keywordScore);
const top = papers.slice(0, KEEP);
seen.ids = [...seen.ids, ...top.map((p) => p.id)].slice(-2000);
return top.map((p) => ({ json: p }));

// ---- shared helpers (inlined by the builder; n8n Code nodes cannot import files) ----
function claudeRequest(system, user, { model = 'claude-haiku-4-5-20251001', maxTokens = 1024 } = {}) {
  // Body for POST https://api.anthropic.com/v1/messages
  return { model, max_tokens: maxTokens, system, messages: [{ role: 'user', content: user }] };
}

function claudeText(response) {
  // Concatenate the text blocks of a Messages API response.
  const blocks = (response && response.content) || [];
  return blocks.filter((b) => b.type === 'text').map((b) => b.text).join('');
}

function extractJson(text) {
  // Models sometimes wrap JSON in prose or code fences: take the outermost {...} or [...].
  if (typeof text !== 'string') return null;
  const starts = [text.indexOf('{'), text.indexOf('[')].filter((i) => i >= 0);
  if (!starts.length) return null;
  const start = Math.min(...starts);
  const end = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));
  if (end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (e) { return null; }
}
// ---- end shared helpers ----

// One request for all candidate papers: cheaper than one call per paper.
const papers = $input.all().map((i) => i.json);
const system = 'You triage research papers for a team working on robotics, AI agents and quantitative trading. ' +
  'Be strict: most papers are not relevant. Reply with JSON only.';
const user = 'Rate each paper 0-10 for relevance and give a one-sentence reason a practitioner would care.\n' +
  'Return a JSON array of {"id": string, "relevance": number, "why": string}.\n\n' +
  JSON.stringify(papers.map((p) => ({ id: p.id, title: p.title, abstract: p.summary })));
return [{ json: { body: claudeRequest(system, user, { maxTokens: 2000 }), count: papers.length } }];

